<script lang="ts">
  import { page } from '$app/state'; import { goto } from '$app/navigation'; import Seo from '#lib/components/ui/Seo.svelte'; import ProductGrid from '#lib/components/products/ProductGrid.svelte'; import ProductQuickView from '#lib/components/products/ProductQuickView.svelte'; import type { Product } from '#lib/data/catalog'; import { products, visibleCollections } from '#lib/data/catalog';
  let query = page.url.searchParams.get('q') ?? ''; let collection = page.url.searchParams.get('collection') ?? ''; let selected:Product|null=null; let opener:HTMLElement|null=null;
  $: filtered = products.filter(p=>(!collection||p.collection===collection)&&(!query||`${p.name} ${p.shortDescription} ${p.description}`.toLowerCase().includes(query.toLowerCase())));
  function sync(){const params=new URLSearchParams();if(query.trim())params.set('q',query.trim());if(collection)params.set('collection',collection);goto(`/shop${params.size?`?${params}`:''}`,{replace:true,reset:false})}
  function setCollection(id:string){collection=id;sync()}
</script>
<Seo title="Shop handmade crochet · islamade" description="Shop crochet bags, charms, bows, sea friends and handmade decor from Islamade."/>
<header class="page-hero shell"><p class="eyebrow">The full collection</p><h1 class="title">Shop handmade crochet</h1><p class="lede">Small-batch pieces made by hand. Open any piece for more photos and details, then order directly through WhatsApp.</p></header>
<section class="section shell"><div class="shop-tools"><div class="shop-search"><label for="shop-search">Search pieces</label><input id="shop-search" type="search" bind:value={query} on:input={sync} placeholder="Try ‘bag’, ‘flower’ or ‘blue’"/></div></div><div class="filters" aria-label="Filter by collection"><button class:active={!collection} class="chip" on:click={()=>setCollection('')}>All pieces</button>{#each visibleCollections as item}<button class:active={collection===item.id} class="chip" on:click={()=>setCollection(item.id)}>{item.name}</button>{/each}</div><p class="results" aria-live="polite">{filtered.length} {filtered.length===1?'piece':'pieces'} found</p><ProductGrid products={filtered} onOpen={(product,trigger)=>{selected=product;opener=trigger}}/></section><ProductQuickView product={selected} {opener} onClose={()=>selected=null}/>
